1196	        .filter(|a| !disabled.contains(a.get_id()))
1197	        .filter_map(|a| {
1198	            a.get_long_and_visible_aliases().map(|longs| {
1199	                longs
1200	                    .into_iter()
1201	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
1202	            })
1203	        })
1204	        .flatten()
