fn run_with(c: &mut Command, raw: Vec<&str>, index: usize, nobin: bool) -> String {
    let mut os: Vec<OsString> = Vec::new();
    if !nobin { os.push(OsString::from("tag")); }
    os.extend(raw.iter().map(OsString::from));
    match complete(c, os, index, None) {
        Ok(v) => v.iter().map(|c| c.get_value().to_string_lossy().into_owned()).collect::<Vec<_>>().join("|"),
        Err(e) => format!("ERR:{}", e),
